public class AncestorsRelativeVisitor : SpanIntersectingVisitor {

	protected PathFilter filter;

	public AncestorsRelativeVisitor(PathFilter filter) {
		this.filter = filter;
	}

	/* @Override */
	public TraceObjectValPath composePath(TraceObjectValPath pre,
			TraceObjectValue value) {
		return pre == null ? TraceObjectValPath.of() : pre.prepend(value);
	}

	/* @Override */
	public VisitResult visitValue(TraceObjectValue value, TraceObjectValPath valPath) {
		KeyPath path = valPath.getPath();
		return VisitResult.result(filter.matches(path),
			filter.ancestorCouldMatchRight(path, true) && value.isObject());
	}

	/* @Override */
	public TraceObject continueObject(TraceObjectValue value) {
		return value.getParent();
	}

	/* @Override */
	public Stream<TraceObjectValue> continueValues(TraceObject @object,
			Lifespan span, TraceObjectValPath pre) {
		Set<string> prevKeys = filter.getPrevKeys(pre.getPath());
		if (prevKeys.isEmpty()) {
			return Stream.empty();
		}

		return @object.getParents(span)
				.stream()
				.filter(v => PathFilter.anyMatches(prevKeys, v.getEntryKey()));
	}
